KEY = {"X-Api-Key": "k"}

def describe(response):
    body = response.json()
    if response.status_code != 200:
        return f"error {response.status_code}: {body['error']}"
    if "data" in body:
        return f"ok: {len(body['data'])} orders"
    return f"ok: order {body['order_id']}"

