import json

text = '{"data": [{"order_id": 1, "amount_cents": 2500, "currency": "EUR", "status": "paid"}, {"order_id": 2, "amount_cents": 9900, "currency": "EUR", "status": "failed"}, {"order_id": 3, "amount_cents": 2000, "currency": "USD", "status": "paid"}, {"order_id": 4, "amount_cents": 2000, "currency": "EUR", "status": "paid"}], "page": 1, "total_pages": 2}'
body = json.loads(text)
totals = {}
for order in body["data"]:
    if order["status"] == "paid":
        count, cents = totals.get(order["currency"], (0, 0))
        totals[order["currency"]] = (count + 1, cents + order["amount_cents"])
for currency in sorted(totals):
    count, cents = totals[currency]
    print(currency, count, f"{cents / 100:.2f}")
print(f"page {body['page']} of {body['total_pages']}")
